<?php defined('ABSPATH') || exit; global $wpdb;
$nav = tj_admin_nav();
tj_page_heading($nav[$section][1] ?? tj_t('Bảng điều khiển', 'Dashboard'));
switch ($section) {
case 'viec-lam': require TJ_DIR . 'templates/admin-jobs.php'; break;
case 'cong-ty': require TJ_DIR . 'templates/admin-companies.php'; break;
case 'danh-muc': require TJ_DIR . 'templates/admin-catalog.php'; break;
case 'ho-so': if (!empty($_GET['application'])) { tj_application_detail(absint($_GET['application']), true); } else { tj_application_list(true); } break;
case 'lich-phong-van':
    if (isset($_GET['edit']) || isset($_GET['application']) || isset($_GET['new'])) {
        $interview = isset($_GET['edit']) ? tj_row('interviews', absint($_GET['edit'])) : null;
        $apps = $wpdb->get_results('SELECT * FROM ' . tj_table('applications') . " WHERE status NOT IN ('passed','rejected') ORDER BY id DESC LIMIT 500", ARRAY_A);
        $options = [];
        foreach ($apps as $app) { $options[$app['id']] = '#' . $app['id'] . ' · ' . $app['candidate_name'] . ' · ' . tj_title((int)$app['job_id']); }
        if ($interview) { $app = tj_row('applications', (int)$interview['application_id']); if ($app) { $options[$app['id']] = '#' . $app['id'] . ' · ' . $app['candidate_name']; } }
        echo '<section class="tj-panel">'; tj_form_start('save_interview', 'tj-stack'); tj_hidden('id', $interview['id'] ?? 0); tj_select('application_id', tj_t('Hồ sơ ứng tuyển', 'Application'), $options, $interview['application_id'] ?? absint($_GET['application'] ?? 0)); tj_input('scheduled_at', tj_t('Thời gian (giờ Việt Nam)', 'Date & time (Vietnam)'), $interview ? wp_date('Y-m-d\TH:i', strtotime($interview['scheduled_at'] . ' UTC')) : wp_date('Y-m-d\T09:00', time() + DAY_IN_SECONDS), 'datetime-local', true); tj_input('location', tj_t('Địa điểm / liên kết phỏng vấn', 'Location / meeting link'), $interview['location'] ?? '', 'text', true); tj_select('result', tj_t('Kết quả', 'Result'), $interview ? tj_results() : ['pending' => tj_results()['pending']], $interview['result'] ?? 'pending'); tj_textarea('note', tj_t('Ghi chú nội bộ', 'Internal note'), $interview['note'] ?? ''); tj_button(); echo '</form></section>';
    } else { ?><p><a class="tj-button" href="<?php echo esc_url(tj_url('quan-tri/lich-phong-van', ['new' => 1])); ?>">+ <?php tj_e('Tạo lịch phỏng vấn', 'Schedule interview'); ?></a></p><?php tj_interview_list(true); } break;
case 'ung-vien': ?>
    <div class="tj-table-wrap"><table class="tj-table"><thead><tr><th><?php tj_e('Họ tên', 'Name'); ?></th><th>Email</th><th><?php tj_e('Điện thoại', 'Phone'); ?></th><th><?php tj_e('Trạng thái', 'Access'); ?></th><th></th></tr></thead><tbody><?php foreach (get_users(['role' => 'tj_candidate', 'number' => 100, 'orderby' => 'registered', 'order' => 'DESC']) as $user) { ?><tr><td><?php echo esc_html($user->display_name); ?></td><td><?php echo esc_html($user->user_email); ?></td><td><?php echo esc_html(get_user_meta($user->ID, 'tj_phone', true)); ?></td><td><?php echo esc_html(get_user_meta($user->ID, 'tj_disabled', true) ? tj_t('Đã khóa', 'Disabled') : tj_t('Hoạt động', 'Active')); ?></td><td><?php tj_form_start('save_user', 'tj-inline tj-confirm'); tj_hidden('id', $user->ID); tj_hidden('disabled', get_user_meta($user->ID, 'tj_disabled', true) ? 0 : 1); tj_button(get_user_meta($user->ID, 'tj_disabled', true) ? 'Mở khóa' : 'Khóa tài khoản', get_user_meta($user->ID, 'tj_disabled', true) ? 'Enable' : 'Disable', 'secondary'); echo '</form>'; ?></td></tr><?php } ?></tbody></table></div><?php break;
case 'thong-bao': tj_notifications(); break;
case 'cai-dat': ?>
    <section class="tj-panel"><h2><?php tj_e('Trợ lý phỏng vấn Gemini', 'Gemini interview assistant'); ?></h2><p><?php echo esc_html(getenv('GEMINI_API_KEY') ? tj_t('Đã có khóa API trên máy chủ.', 'API key is configured on the server.') : tj_t('Chưa có khóa API. Website đang hỗ trợ demo.', 'No API key configured. Demo practice is available.')); ?></p><?php tj_form_start('save_settings', 'tj-stack'); tj_input('model', 'Gemini model', get_option('tj_ai_model', getenv('GEMINI_MODEL') ?: 'gemini-flash-latest'), 'text', true); tj_textarea('prompt', tj_t('Hướng dẫn bổ sung cho bot', 'Additional interviewer instructions'), get_option('tj_ai_prompt', '')); ?><label class="tj-check"><input type="checkbox" name="demo" value="1" <?php checked(get_option('tj_ai_demo', false)); ?>> <?php tj_e('Luôn dùng chế độ demo', 'Always use demo mode'); ?></label><?php tj_button(); ?></form><p><button type="button" id="tj-ai-test" class="tj-button secondary"><?php tj_e('Kiểm tra kết nối Gemini', 'Test Gemini connection'); ?></button><span id="tj-ai-test-result" role="status"></span></p><p class="tj-muted"><?php tj_e('Khóa được đặt trong GEMINI_API_KEY trên máy chủ; không nhập hoặc hiển thị trong trình duyệt.', 'Set GEMINI_API_KEY on the server. The key is never entered or displayed here.'); ?></p><hr><h2><?php tj_e('Ngôn ngữ hiển thị', 'Display language'); ?></h2><p><?php tj_e('Website hỗ trợ Tiếng Việt và Tiếng Anh. Dùng nút chuyển ngôn ngữ ở thanh trên. Nội dung song ngữ được quản lý ngay trong form tin tuyển dụng và công ty.', 'Vietnamese and English are supported. Use the language switch in the header. Edit bilingual content in job and company forms.'); ?></p></section><?php break;
default:
    $total = (int)$wpdb->get_var('SELECT COUNT(*) FROM ' . tj_table('applications'));
    $waiting = (int)$wpdb->get_var('SELECT COUNT(*) FROM ' . tj_table('applications') . " WHERE status IN ('submitted','reviewing')");
    $passed = (int)$wpdb->get_var('SELECT COUNT(*) FROM ' . tj_table('applications') . " WHERE status='passed'");
    $jobs = tj_jobs([], true);
    ?><div class="admin-grid"><section class="admin-welcome-banner"><div class="admin-welcome-info"><h2><?php tj_e('Bảng điều khiển', 'Recruitment dashboard'); ?></h2><p><?php tj_e('Chào mừng quay trở lại! Dưới đây là tình hình tuyển dụng của bạn.', 'Welcome back! Here is your recruitment overview.'); ?></p></div><div class="admin-welcome-badge"><?php echo esc_html(wp_date('d/m/Y')); ?></div></section><section class="admin-metrics-grid"><?php foreach ([['theme-pink', tj_t('Tổng số ứng tuyển', 'Total applications'), $total], ['theme-yellow', tj_t('Đang chờ xử lý', 'Awaiting review'), $waiting], ['theme-blue', tj_t('Hồ sơ đạt', 'Passed applications'), $passed]] as [$theme, $label, $count]) { ?><article class="admin-metric-card <?php echo esc_attr($theme); ?>"><div class="admin-metric-card-header"><span class="admin-metric-card-title"><?php echo esc_html($label); ?></span></div><div class="admin-metric-card-value"><?php echo (int)$count; ?></div><div class="admin-metric-card-footer"><?php tj_e('Dữ liệu thực từ hệ thống', 'Live system data'); ?></div></article><?php } ?></section><div class="admin-layout-split"><section class="saas-card"><div class="tj-row tj-between"><h3><?php tj_e('Tin tuyển dụng gần đây', 'Recent job postings'); ?></h3><a href="<?php echo esc_url(tj_url('quan-tri/viec-lam')); ?>"><?php tj_e('Quản lý', 'Manage'); ?> →</a></div><p class="tj-muted"><?php echo (int)$jobs['total']; ?> <?php tj_e('tin tuyển dụng', 'job postings'); ?> · <?php echo (int)count_users()['avail_roles']['tj_candidate']; ?> <?php tj_e('ứng viên', 'candidates'); ?></p><div class="tj-stack"><?php foreach (array_slice($jobs['posts'], 0, 5) as $job) { ?><a class="tj-mini-job" href="<?php echo esc_url(tj_url('quan-tri/viec-lam', ['edit' => $job->ID])); ?>"><strong><?php echo esc_html(tj_title($job->ID)); ?></strong><small><?php echo esc_html(tj_company_name($job->ID) . ' · ' . tj_salary($job->ID)); ?></small></a><?php } ?></div></section><section class="saas-card"><h3><?php tj_e('Phân tích trạng thái hồ sơ', 'Application status breakdown'); ?></h3><div class="tj-status-chart"><?php foreach (tj_statuses() as $key => $label) { $count = (int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM ' . tj_table('applications') . ' WHERE status=%s', $key)); ?><div><div class="tj-row tj-between"><span><?php echo esc_html($label); ?></span><strong><?php echo $count; ?></strong></div><meter value="<?php echo $count; ?>" min="0" max="<?php echo max(1, $total); ?>"><?php echo $count; ?></meter></div><?php } ?></div></section></div><section class="saas-card"><h3><?php tj_e('Hoạt động gần đây', 'Recent activity'); ?></h3><div class="tj-table-wrap"><table class="tj-table"><thead><tr><th><?php tj_e('Thao tác', 'Action'); ?></th><th><?php tj_e('Người xử lý', 'Actor'); ?></th><th><?php tj_e('Thời gian', 'Time'); ?></th></tr></thead><tbody><?php foreach (tj_rows('audit', 10) as $log) { $actor = get_user_by('id', $log['actor_id']); ?><tr><td><?php echo esc_html($log['action'] . ' #' . $log['entity_id']); ?></td><td><?php echo esc_html($actor ? $actor->display_name : 'System'); ?></td><td><?php echo esc_html(tj_date($log['created_at'], true)); ?></td></tr><?php } ?></tbody></table></div></section></div><?php
}
